private SplitResponse doSplit(String parentBatchNo, SplitRequest request) {
    TimberBatch parent = repository.lockBatchByNo(parentBatchNo)
        .orElseThrow(() -> ApiException.notFound("BATCH_NOT_FOUND", "批次不存在: " + parentBatchNo));
    if (!parent.leaf()) throw unprocessable("BATCH_ALREADY_SPLIT", "父批次已拆分，仅作来源节点");
    repository.findPendingTransferForBatch(parent.id()).ifPresent(t -> { throw conflict("TRANSFER_PENDING", ...); });
    SplitValidator.checkDistinctBatchNos(request.children()).ifPresent(msg -> { throw unprocessable("DUPLICATE_CHILD_BATCH_NO", msg); });
    SplitValidator.checkWeightConservation(parent.weightKg(), request.children()).ifPresent(msg -> { throw unprocessable("WEIGHT_NOT_CONSERVED", msg); });
    for (child : request.children()) {
        if (repository.findBatchByNo(child.batchNo()).isPresent()) throw conflict("BATCH_NO_EXISTS", ...);
    }
    List<BatchView> views = new ArrayList<>();
    for (child) { TimberBatch c = repository.insertBatch(child.batchNo(), parent.sourceId(), parent.id(), parent.voucherNo(), parent.species(), child.weightKg(), parent.holder()); views.add(toView(c)); }
    repository.markNonLeaf(parent.id());
    return new SplitResponse(parentBatchNo, views);
}
