public TraceResponse trace(String batchNo) {
    TimberBatch batch = repository.findBatchByNo(batchNo).orElseThrow(404);
    LinkedList<TraceNode> chain = new LinkedList<>();
    TimberBatch current = batch;
    while (true) {
        chain.addFirst(new TraceNode(current.batchNo(), current.weightKg(), current.holder(), current.leaf()));
        if (current.parentId() == null) break;
        current = repository.findBatchById(current.parentId()).orElseThrow(() -> new IllegalStateException("父批次缺失"));
    }
    return new TraceResponse(batch.batchNo(), batch.voucherNo(), batch.species(), batch.weightKg(), batch.holder(), chain);
}
