package com.example.starter.timber;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import com.example.starter.timber.web.ApiException;
import com.example.starter.timber.web.TimberDtos.RegisterSourceRequest;
import com.example.starter.timber.web.TimberDtos.SplitRequest;
import com.example.starter.timber.web.TimberDtos.TransferRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 并发竞争测试：同一叶子批次的拆分与移交、拆分与拆分竞争时只有一个成功，
 * 且并发拆分保持重量守恒。两个线程用闩锁同时起跑，结果带超时获取。
 */
@SpringBootTest
class TimberConcurrencyTest {

    @Autowired
    private TimberService service;

    @Autowired
    private JdbcTemplate jdbc;

    private ExecutorService pool;

    @BeforeEach
    void setUp() {
        jdbc.update("DELETE FROM request_log");
        jdbc.update("DELETE FROM transfer_order");
        jdbc.update("DELETE FROM timber_batch");
        jdbc.update("DELETE FROM timber_source");
        pool = Executors.newFixedThreadPool(2);
    }

    @AfterEach
    void tearDown() {
        pool.shutdownNow();
    }

    private void registerSource(String voucher, int weight) {
        service.registerSource(new RegisterSourceRequest(voucher, "红松", weight, "加工点A"));
    }

    /** 并发执行两个操作，返回各自结果：true成功，false因业务冲突失败。 */
    private List<Boolean> race(Runnable first, Runnable second) throws Exception {
        CountDownLatch ready = new CountDownLatch(2);
        CountDownLatch start = new CountDownLatch(1);
        Runnable wrappedFirst = () -> await(ready, start, first);
        Runnable wrappedSecond = () -> await(ready, start, second);
        Future<?> f1 = pool.submit(wrappedFirst);
        Future<?> f2 = pool.submit(wrappedSecond);
        assertTrue(ready.await(10, TimeUnit.SECONDS), "线程未就绪");
        start.countDown();
        f1.get(20, TimeUnit.SECONDS);
        f2.get(20, TimeUnit.SECONDS);
        return List.of(OutcomeHolder.firstOk, OutcomeHolder.secondOk);
    }

    private static class OutcomeHolder {
        static volatile boolean firstOk;
        static volatile boolean secondOk;
    }

    private static void await(CountDownLatch ready, CountDownLatch start, Runnable action) {
        ready.countDown();
        try {
            start.await(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException(e);
        }
        boolean ok = true;
        try {
            action.run();
        } catch (ApiException e) {
            ok = false;
        }
        if (ready.getCount() == 1 || OutcomeHolder.firstOk == false && OutcomeHolder.secondOk == false) {
            // 占位，实际赋值在下方按线程区分
        }
        assign(ok);
    }

    private static final Object ASSIGN_LOCK = new Object();
    private static volatile boolean firstAssigned;

    private static void assign(boolean ok) {
        synchronized (ASSIGN_LOCK) {
            if (!firstAssigned) {
                OutcomeHolder.firstOk = ok;
                firstAssigned = true;
            } else {
                OutcomeHolder.secondOk = ok;
            }
        }
    }

    @Test
    void splitAndTransferRaceExactlyOneSucceeds() throws Exception {
        registerSource("V-C1", 100);
        firstAssigned = false;
        OutcomeHolder.firstOk = false;
        OutcomeHolder.secondOk = false;

        Runnable split = () -> service.split("BATCH-V-C1", new SplitRequest("S-C1",
